const datos = $input.all().map(item => item.json);

if (datos.length === 0) {
  return [
    {
      json: {
        resumen: `RESUMEN DIARIO DE DEVOLUCIONES

No existen solicitudes nuevas para este período.

Total de solicitudes: 0
Monto total procesado: $0

No se procesaron nuevos registros porque no existen solicitudes en la tabla.`,
        total_solicitudes: 0,
        monto_total: 0,
        tasa_aprobacion_automatica: 0
      }
    }
  ];
}

const totalSolicitudes = datos.reduce(
  (sum, r) => sum + Number(r.count_id_solicitud || 0),
  0
);

const montoTotal = datos.reduce(
  (sum, r) => sum + Number(r.sum_monto_num || 0),
  0
);

const aprobadas = datos.find(
  r => r.ruta === 'APROBACION'
)?.count_id_solicitud || 0;

const tasaAprobacion = totalSolicitudes > 0
  ? (Number(aprobadas) / totalSolicitudes * 100).toFixed(2)
  : '0.00';

let resumen = `RESUMEN DIARIO DE DEVOLUCIONES

Total de solicitudes: ${totalSolicitudes}
Monto total procesado: $${montoTotal.toLocaleString('es-CL')}

DETALLE POR RUTA:
`;

for (const r of datos) {
  resumen += `- ${r.ruta}: ${r.count_id_solicitud} solicitudes | $${Number(r.sum_monto_num).toLocaleString('es-CL')}
`;
}

resumen += `
Tasa de aprobación automática: ${tasaAprobacion}%

Frecuencia de ejecución: una vez al día a las 20:00.
Si no existen solicitudes nuevas, se informará que no hubo solicitudes para el período.`;

return [
  {
    json: {
      resumen,
      total_solicitudes: totalSolicitudes,
      monto_total: montoTotal,
      tasa_aprobacion_automatica: Number(tasaAprobacion)
    }
  }
];
